'use strict';
window.initLiveDirectory=function(root){
 const section=root.querySelector('.live-discovery');if(!section)return;
 const platform=root.dataset.platform,brand=platform==='x'?'X':'Twitch',list=section.querySelector('.live-channel-list'),search=section.querySelector('.live-search'),category=section.querySelector('.live-category'),only=section.querySelector('.live-only'),status=section.querySelector('.directory-status'),more=section.querySelector('.directory-more'),refresh=section.querySelector('.directory-refresh'),monitorForm=section.querySelector('.monitor-form'),monitorInput=section.querySelector('.monitor-name'),monitorList=section.querySelector('.monitor-list'),announcement=section.querySelector('.live-announcement'),banner=root.querySelector('.live-banner'),track=banner.querySelector('.live-track'),pause=banner.querySelector('.ticker-pause'),shelf=root.querySelector('.featured-channel-list');
 const key='iptv-'+platform+'-monitors',limit=platform==='x'?4:12,pattern=platform==='x'?/^[a-zA-Z0-9_]{1,15}$/:/^[a-zA-Z0-9_]{1,25}$/;
 let monitors=[];try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))monitors=saved.filter(x=>typeof x==='string'&&pattern.test(x)).slice(0,limit);}catch{}
 let snapshot=null,channels=[],catalog=[],count=12,featuredCount=6,timer,request,disposed=false,generation=0,stale=false,highlighted=[],cursor=0,batches=0,lastFeatured=0,scanInterval=platform==='x'?10000:5000,scanned=new Set(),catalogVersion='',watchEpoch=0;
 const statuses=new Map();
 function node(tag,className,value){const n=document.createElement(tag);if(className)n.className=className;if(value)n.textContent=value;return n;}
 function isLive(c){return c.state==='live'&&!stale&&(!c.checkedAt||Date.now()-Date.parse(c.checkedAt)<180000);}
 function order(a,b){return Number(Boolean(b.featured))-Number(Boolean(a.featured))||Number(isLive(b))-Number(isLive(a))||(a.catalogRank??99999)-(b.catalogRank??99999)||(b.viewers||0)-(a.viewers||0);}
 function rebuild(){const ids=new Set(catalog.map(c=>c.id));channels=catalog.map(c=>({...c,state:'unchecked',title:'Live status has not been checked yet.',url:platform==='twitch'?'https://www.twitch.tv/'+c.username:'',...statuses.get(c.id),category:c.category,featured:Boolean(c.featured),catalogRank:c.catalogRank}));for(const c of statuses.values())if(!ids.has(c.id))channels.push(c);channels.sort(order);}
 function play(item){if(!item.url)return;root.querySelector('#social-url').value=item.url;root.querySelector('#social-form').requestSubmit();root.querySelector('#social-form').scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
 async function watch(item,button){const currentWatch=++watchEpoch;
  if(item.url&&['live','replay','video'].includes(item.state)&&!stale){play(item);return;}
  if(button){button.disabled=true;setControlLabel(button,'Checking…','arrow-path');}
  try{const p=new URLSearchParams({platform,check:item.username}),r=await fetch('/api/live-directory?'+p),data=await r.json();if(!r.ok)throw Error(data.error||'This channel could not be checked.');if(disposed||currentWatch!==watchEpoch)return;update(data,false);const checked=data.channels.find(c=>c.id===item.id);if(checked?.url&&['live','replay','video'].includes(checked.state))play(checked);else status.textContent=checked?.title||'No public video is available from this channel right now.';}
  catch(e){if(!disposed&&currentWatch===watchEpoch)status.textContent=e.message;}
  finally{if(button?.isConnected){button.disabled=false;setControlLabel(button,'Check channel','play');}}
 }
 function card(item,featured=false){
  const article=node('article','live-channel'+(featured?' featured-channel':'')),preview=node('div','channel-preview'),info=node('div','discovery-channel-info'),header=node('div','discovery-channel-header');const src=item.poster||item.avatar;
  if(src){const img=node('img',item.poster?'channel-thumbnail':'channel-avatar');img.src=src;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>img.remove());preview.append(img);}else preview.innerHTML=heroIcon('play');
  const label=isLive(item)?'Live':item.state==='live'?'Last seen live':item.state==='replay'?'Replay':item.state==='video'?'Video':item.state==='offline'?(platform==='x'?'No public live found':'Offline'):item.state==='unchecked'?'Awaiting check':'Status unavailable';preview.append(node('span','discovery-state',label));header.append(node('strong','',item.name),node('span','',item.category));info.append(header,node('p','discovery-handle','@'+item.username),node('p','discovery-title',item.title||'Check this channel for public live video.'));
  if(Number.isFinite(item.viewers))info.append(node('p','discovery-viewers',new Intl.NumberFormat().format(item.viewers)+' viewers'));
  if(item.liveCategory&&item.liveCategory!==item.category)info.append(node('p','discovery-viewers',item.liveCategory));
  const button=node('button');button.type='button';button.dataset.watch=item.id;const action=isLive(item)?'Watch live':['replay','video'].includes(item.state)?'Watch video':'Check channel';setControlLabel(button,action,'play');button.setAttribute('aria-label',action+': '+item.name);button.addEventListener('click',()=>watch(item,button));info.append(button);article.append(preview,info);return article;
 }
 function renderFeatured(){if(!shelf)return;const featured=channels.filter(c=>c.featured).sort(order);shelf.replaceChildren();for(const c of featured.slice(0,featuredCount))shelf.append(card(c,true));root.querySelector('.featured-more').hidden=featured.length<=featuredCount;root.querySelector('.featured-summary').textContent=featured.length+' editorial picks · live channels first';const links=root.querySelector('.featured-category-links');links.replaceChildren();const groups=[...new Set(catalog.map(c=>c.category))].sort();for(const name of groups){const button=node('button','category-jump',name);button.type='button';button.addEventListener('click',()=>{category.value=name;count=12;render();section.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});links.append(button);}}
 function render(){const needle=search.value.trim().toLowerCase(),selected=channels.filter(c=>(category.value==='all'||c.category===category.value)&&(!only.checked||isLive(c))&&[c.name,c.username,c.title,c.category,c.liveCategory].join(' ').toLowerCase().includes(needle)).sort(order),focused=list.contains(document.activeElement)?document.activeElement.dataset.watch:null;list.replaceChildren();
  const groups=new Map();for(const c of selected){if(!groups.has(c.category))groups.set(c.category,[]);groups.get(c.category).push(c);}const perGroup=category.value==='all'?Math.max(3,Math.floor(count/4)):count;let hidden=false;
  for(const [name,rows] of groups){const group=node('section','channel-category-group'),heading=node('div','category-group-heading'),grid=node('div','category-channel-grid');heading.append(node('h3','',name),node('span','',rows.length+' channels'));group.append(heading,grid);for(const c of rows.slice(0,perGroup))grid.append(card(c));if(rows.length>perGroup)hidden=true;list.append(group);}
  if(!selected.length)list.append(node('p','directory-empty',snapshot||catalog.length?'No channels match these filters. Try another category or turn off Live only.':'Loading the channel catalog…'));more.hidden=!hidden;section.querySelector('.directory-count').textContent=selected.length+' '+(selected.length===1?'channel':'channels');
  const summary=section.querySelector('.catalog-summary');if(summary)summary.textContent=catalog.length?catalog.length+' catalog accounts monitored · '+Math.min(scanned.size,catalog.length)+' checked in this scan':'Loading monitored accounts…';
  if(focused)[...list.querySelectorAll('[data-watch]')].find(b=>b.dataset.watch===focused)?.focus({preventScroll:true});
 }
 function ticker(){const live=channels.filter(c=>isLive(c)&&c.url).sort((a,b)=>Number(highlighted.includes(b.id))-Number(highlighted.includes(a.id))||order(a,b));track.replaceChildren();banner.querySelector('.ticker-label').textContent=(stale?'Last checked':'Live now')+(live.length?' · '+live.length:'');
  if(!live.length){track.append(node('span','ticker-empty',scanned.size<catalog.length?'No verified live channels in the latest checks. More accounts are being checked.':snapshot?.partial?'Live status is unavailable for some monitored accounts.':'No verified monitored channels are live right now.'));pause.hidden=true;return;}
  pause.hidden=false;const copy=node('div','ticker-copy');for(const c of live.slice(0,20)){const b=node('button','ticker-item',c.name+' is live — '+c.title.slice(0,90));b.type='button';b.addEventListener('click',()=>play(c));copy.append(b);}track.append(copy);const duplicate=copy.cloneNode(true);duplicate.setAttribute('aria-hidden','true');[...duplicate.querySelectorAll('button')].forEach((b,i)=>{b.tabIndex=-1;b.addEventListener('click',()=>play(live[i]));});track.append(duplicate);track.style.setProperty('--ticker-duration',Math.max(35,Math.min(120,live.length*8))+'s');
 }
 function options(){const current=category.value,categories=[...new Set(channels.map(c=>c.category))].sort();category.replaceChildren(new Option('All categories','all'));for(const c of categories)category.append(new Option(c,c));category.value=categories.includes(current)?current:'all';}
 function persist(){try{localStorage.setItem(key+'-status',JSON.stringify({catalogVersion,storedAt:Date.now(),scanCursor:cursor,scanned:[...scanned],channels:[...statuses.values()]}));}catch{}}
 function update(data,scanning=true){const newly=[];for(const row of data.channels){const previous=statuses.get(row.id),fresh={...row,checkedAt:row.checkedAt||data.checkedAt};if(previous&&previous.state==='offline'&&fresh.state==='live')newly.push(fresh);if(!previous||Date.parse(fresh.checkedAt)>=Date.parse(previous.checkedAt||0))statuses.set(row.id,fresh);if(scanning&&catalog.some(c=>c.id===row.id))scanned.add(row.id);}
  highlighted=newly.map(c=>c.id);stale=false;snapshot=data;batches=data.batchCount||batches;scanInterval=data.scanIntervalSeconds?data.scanIntervalSeconds*1000:scanInterval;rebuild();options();announcement.textContent=newly.map(c=>c.name+' is now live.').join(' ');renderFeatured();ticker();render();persist();status.textContent='Featured accounts are refreshed every minute; the full catalog is checked in rotating batches. '+(data.partial?'Some accounts could not be verified. ':'')+'Latest check '+new Date(data.checkedAt).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})+'.';
 }
 function schedule(){clearTimeout(timer);if(!disposed&&!document.hidden)timer=setTimeout(()=>load(Date.now()-lastFeatured>=60000?-1:cursor),scanInterval);}
 async function load(batch=-1){if(disposed||document.hidden||request)return;clearTimeout(timer);const current=++generation,controller=new AbortController();request=controller;const timeout=setTimeout(()=>controller.abort(),55000);refresh.disabled=true;setControlLabel(refresh,'Checking…','arrow-path');section.setAttribute('aria-busy','true');
  try{const params=new URLSearchParams({platform});if(batch>=0)params.set('batch',String(batch));else if(monitors.length)params.set('channels',monitors.join(','));const r=await fetch('/api/live-directory?'+params,{signal:controller.signal}),data=await r.json();if(!r.ok)throw Error(data.error||'Live checks are unavailable.');if(!disposed&&current===generation){update(data);if(batch<0)lastFeatured=Date.now();else{cursor=(batch+1)%Math.max(1,batches);if(cursor===0)scanned=new Set();persist();}}}
  catch(e){if(!disposed&&current===generation){announcement.textContent='';stale=true;rebuild();renderFeatured();ticker();render();status.textContent=(snapshot?'Showing the last checked results. ':'')+(e.name==='AbortError'?'This batch took too long.':e.message)+' Other accounts will continue to be checked.';if(batch>=0)cursor=(batch+1)%Math.max(1,batches);else lastFeatured=Date.now();}}
  finally{clearTimeout(timeout);if(current===generation){request=null;refresh.disabled=false;setControlLabel(refresh,'Refresh','arrow-path');refresh.classList.remove('is-loading');section.setAttribute('aria-busy','false');schedule();}}
 }
 function renderMonitors(){monitorList.replaceChildren();for(const name of monitors){const b=node('button','monitor-remove','@'+name+' · Remove');b.type='button';b.setAttribute('aria-label','Stop monitoring '+name);b.addEventListener('click',()=>{monitors=monitors.filter(n=>n!==name);saved();});monitorList.append(b);}}
 function saved(){try{localStorage.setItem(key,JSON.stringify(monitors));}catch{}renderMonitors();generation++;request?.abort();request=null;load(-1);}
 monitorForm.addEventListener('submit',e=>{e.preventDefault();const name=monitorInput.value.trim().replace(/^@/,'').toLowerCase();if(!pattern.test(name)){status.textContent='Enter a valid '+brand+' username.';return;}if(monitors.includes(name)){status.textContent='You already monitor @'+name+'.';return;}if(monitors.length>=limit){status.textContent='You can add '+limit+' personal accounts alongside the full featured catalog.';return;}monitors.push(name);monitorInput.value='';saved();});
 root.querySelector('#social-form').addEventListener('submit',()=>{watchEpoch++;});root.querySelector('#social-clear').addEventListener('click',()=>{watchEpoch++;});
 for(const input of [search,category,only])input.addEventListener(input===search?'input':'change',()=>{count=12;render();});more.addEventListener('click',()=>{count+=12;render();});refresh.addEventListener('click',()=>load(-1));root.querySelector('.featured-more')?.addEventListener('click',()=>{featuredCount+=6;renderFeatured();});pause.addEventListener('click',()=>{const paused=banner.classList.toggle('is-paused');pause.setAttribute('aria-pressed',String(paused));setControlLabel(pause,paused?'Resume notices':'Pause notices',paused?'play':'stop');});
 function visibility(){clearTimeout(timer);generation++;request?.abort();request=null;if(!document.hidden)load(-1);}document.addEventListener('visibilitychange',visibility);window.addEventListener('pagehide',()=>{disposed=true;watchEpoch++;generation++;clearTimeout(timer);request?.abort();document.removeEventListener('visibilitychange',visibility);},{once:true});
 async function boot(){setControlLabel(pause,'Pause notices','stop');setControlLabel(refresh,'Refresh','arrow-path');refresh.classList.remove('is-loading');renderMonitors();
  try{const r=await fetch('/featured-catalog.json');if(!r.ok)throw Error('Catalog unavailable.');const data=await r.json();if(disposed)return;catalog=data.platforms?.[platform]?.channels||[];catalogVersion=data.generatedAt||'';batches=Math.ceil(catalog.length/(platform==='x'?8:20));try{const cached=JSON.parse(localStorage.getItem(key+'-status')||'null');if(cached?.catalogVersion===catalogVersion&&Date.now()-cached.storedAt<24*60*60*1000){for(const c of cached.channels||[])statuses.set(c.id,c);if(Number.isInteger(cached.scanCursor)&&cached.scanCursor>=0&&cached.scanCursor<batches)cursor=cached.scanCursor;scanned=new Set((cached.scanned||[]).filter(id=>catalog.some(c=>c.id===id)));}}catch{}rebuild();options();renderFeatured();render();ticker();}
  catch{status.textContent='The full catalog could not load. Checking featured channels instead.';}load(-1);
 }
 boot();
};
